import { ListScreenConfig } from '../../../shared/screens/screen.types';
import { ServiceCategoryRow } from '../masters.api';

// Generated by masters_lookup.py's factory, so `list_rows` accepts EXACTLY
// three query params — search, include_inactive, format. That is the whole of
// what can round-trip to the server here, and this sub-master has no other
// dimension to filter on anyway: masters_simple.py:200-205 declares its fields
// as {name, description} only, so the response row is {id, is_active, name,
// description} and nothing more.
//
// The prototype's Status filter (Active / Inactive / All Statuses) is
// deliberately NOT declared as a FilterDef: `includeInactiveParam` below
// already renders the shared "Show inactive" control and chips it as
// "Status: Including inactive". A second Status <select> could not reach that
// flag, so choosing "Inactive" in it while the checkbox was off would empty the
// list for no visible reason.
const config: ListScreenConfig<ServiceCategoryRow> = {
  shape: 'list',
  id: 'masters.service_categories',
  title: 'Service Category',
  specRef: '§3.12',
  recordNoun: 'service category',
  // The prototype's list screen carries no desc of its own; this is its own
  // wording for the same sub-master, from the Add screen (data.js
  // masters.servicecategory.add).
  description: "Meshrd's own service lines, for tagging Opportunities, Projects and Invoices.",
  endpoint: '/masters/service-categories',
  exportable: true,
  rowId: (row) => row.id,
  rowRoute: (row) => ['/masters/service-categories', row.id, 'edit'],
  createRoute: ['/masters/service-categories', 'new'],
  createLabel: 'Add Service Category',
  // Both are real params on this endpoint (masters_lookup.py:168-169), so the
  // search box and the Active-by-default rule round-trip and the export is
  // exactly what is on screen rather than approximately.
  searchParam: 'search',
  includeInactiveParam: 'include_inactive',
  // §3a — masters_simple.py now passes search_field=["name", "code"].
  searchFields: ['name', 'code'],
  filters: [
    {
      key: 'is_referenced',
      label: 'Used',
      kind: 'tristate',
      transport: 'server',
      param: 'is_referenced',
      allLabel: 'Used — Any',
    },
  ],
  columns: [
    { key: 'name', header: 'Service Category', cellClass: 'cell-strong' },
    { key: 'code', header: 'Code', type: 'code' },
    // Not in the prototype's column list, but §3.12's Screen Design says "List
    // view shows: Name, Description, Status" and the field is really stored.
    { key: 'description', header: 'Description' },
    { key: 'is_active', header: 'Status', type: 'status', compute: (row) => (row.is_active ? 'Active' : 'Inactive') },
    { key: 'is_referenced', header: 'Used', type: 'status' },
  ],
  // §3.0 rule 1: "Delete and Deactivate are Super Admin only… only Super Admin
  // sees it." Both are gated on the 'delete' screen action — the same action
  // the API itself checks via require_screen(screen_key, action="delete").
  //
  // QUEUED — see this group's audit report: masters_lookup.py's factory has no
  // reverse of POST /{id}/deactivate, so a deactivated category can never come
  // back via this UI even though §3.12's own Fields Table lists Status as a
  // normal editable toggle. This button targets the endpoint that reversal
  // needs (POST /{id}/activate) ahead of the backend adding it — inert (404)
  // until it does, same pattern this session used for Financial Year's End Date.
  rowActions: [
    {
      label: 'Activate',
      endpoint: (row) => `/masters/service-categories/${row.id}/activate`,
      screenAction: 'delete',
      visible: (row) => !row.is_active,
    },
    {
      label: 'Deactivate',
      endpoint: (row) => `/masters/service-categories/${row.id}/deactivate`,
      screenAction: 'delete',
      visible: (row) => row.is_active,
      confirm: '§3.12 asks for a confirmation before deactivating a category already tagged on an Opportunity, Project or Invoice. Existing records keep it; it just stops being offered on new ones. Continue?',
    },
    {
      // The factory's real DELETE /{id}. The database's own ON DELETE RESTRICT
      // keys turn it into a 409 the moment anything references the row, which
      // is exactly §3.12's "never hard-deleted once tagged" rule enforced by
      // the schema rather than by a check here.
      label: 'Delete',
      method: 'DELETE',
      endpoint: (row) => `/masters/service-categories/${row.id}`,
      screenAction: 'delete',
      visible: (row) => !row.is_referenced,
      confirm: 'Delete this service category permanently? This only succeeds while nothing references it.',
    },
  ],
  defaultPageSize: 50,
  emptyText: 'No service categories configured.',
};

export default config;
